def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    own = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_def = sum(1 for x in opp if x == 'D')
    own_def = sum(1 for x in own if x == 'D')

    test_performed = False
    test_retaliated = False
    if n >= 7:
        if history[5][0] == 'D' and history[6][0] == 'D':
            if all(h[1] == 'C' for h in history[:5]):
                test_performed = True
                test_retaliated = (history[6][1] == 'D')

    if test_performed:
        if test_retaliated:
            if n == 7 or n == 8:
                return 'C'
        else:
            if opp_def == 0:
                return 'D'

    if not test_performed and opp_def == 0 and own_def == 0:
        if n < 5:
            return 'C'
        if n == 5:
            return 'D'
        if n == 6:
            return 'D'

    if opp[-1] == 'D':
        return 'D'
    if opp_def > own_def and n >= 50:
        return 'D'
    if n >= 2 and opp[-1] == 'D' and opp[-2] == 'D':
        return 'D'
    if opp_def <= n // 4:
        return 'C'
    if opp_def > n // 2:
        if rng.random() < 0.7:
            return 'D'
        return 'C'
    return 'C'
